package export

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// BenchmarkGenerate profiles the exporter against a caller-provided checkout.
// Exported snapshots live in the benchmark temp directory.
func BenchmarkGenerate(b *testing.B) {
	dir := os.Getenv("DRVGO_BENCH_DIR")
	if dir == "" {
		b.Skip("set DRVGO_BENCH_DIR and optionally DRVGO_BENCH_PACKAGE")
	}
	tc := os.Getenv("DRVGO_BENCH_TOOLCHAIN")
	if tc == "" {
		var err error
		tc, err = Toolchain()
		if err != nil {
			b.Fatal(err)
		}
	}
	o := Options{Dir: dir, Out: filepath.Join(b.TempDir(), "export"), Package: os.Getenv("DRVGO_BENCH_PACKAGE"), Toolchain: tc, ModuleCache: os.Getenv("DRVGO_BENCH_MODULE_CACHE")}
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		if _, err := Generate(o); err != nil {
			b.Fatal(err)
		}
	}
}

var renderedScripts string

func BenchmarkRenderScripts(b *testing.B) {
	path := os.Getenv("DRVGO_BENCH_GRAPH")
	if path == "" {
		b.Skip("set DRVGO_BENCH_GRAPH")
	}
	data, err := os.ReadFile(filepath.Join(path, "graph.json"))
	if err != nil {
		b.Fatal(err)
	}
	var graph Graph
	if err := json.Unmarshal(data, &graph); err != nil {
		b.Fatal(err)
	}
	want, err := os.ReadFile(filepath.Join(path, "scripts.nix"))
	if err != nil {
		b.Fatal(err)
	}
	if nixScripts(graph.Units) != string(want) {
		b.Fatal("rendered script bytes changed")
	}
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		renderedScripts = nixScripts(graph.Units)
	}
}
